#include "stdafx.h"#include "SafetyManager.h"#include <macros/AutoCloser.h>#include <macros/StrHelps.h>#include <vector>extern int g_chVer;KSafetyManager::e_RestResult KSafetyManager::Load( LPCSTR pszPrj ){  char szPath[_MAX_PATH];  char tmp[64];  sprintf_s( tmp, "%s_FLDProperties", pszPrj );  GetPathToSmFile( szPath, pszPrj, tmp, ".csv" );  FILE *pFileIn = NULL;  errno_t res = fopen_s( &pFileIn, szPath, "rt" );  if( res )    return err_CommonErr;  KAutoCloser<FILE*> file( pFileIn, fclose );  std::vector<SFldsInfo> flds;  char szLine[2048] = {};  while( fgets( szLine, _countof(szLine)-1, pFileIn ) )  {    char row[18][128] = { 0 };    int C = SplitString( szLine, row, ';', false );    ASSD( C < _countof(row) );    SFldsInfo fld;    fld.nFld = atoi( row[0] );    if( !fld.nFld )      continue;    strcpy_s( fld.szTagName, row[1] );    strcpy_s( fld.szTitle, row[2] );    if( strstr(row[7], "Program") )      fld.type = SFldsInfo::Program;    else if( strstr(row[7], "Comment") )      fld.type = SFldsInfo::Comment;    else if( strstr(row[7], "Function") )      fld.type = SFldsInfo::Function;    else if( strstr(row[7], "Tag number index") )      fld.type = SFldsInfo::Tag_number_index;    else if( strstr(row[7], "FLD index") )      fld.type = SFldsInfo::FLD_index;    else if( strstr(row[7], "Equation block") )      fld.type = SFldsInfo::Equation_block;    else    {      ASSD(0);    }    flds.push_back( fld );  }  char Path[_MAX_PATH];  GetPathToSmFile( Path, pszPrj, pszPrj, ".*" );  SUniTemp temp;  if( !BuildListFsc( this, Path, temp, &flds[0], (int)flds.size() ) )    return err_CommonErr;  const UINT nCount0 = mList.Count();  //создание точек не прописанных ни на каком экране  for( int n = 0; n < m_kFSC_Info; n++ )  {    CFSC_Info &info = m_FSC_Info[n];    if( !(info.PLCADDR && '0'==info.szFLDNumber[0]) )      continue;    SFscBase obj;    BYTE buf[128] = { 0 };    SfscAbstruct &dat = *(SfscAbstruct*)buf;    strcpy_s( (char*)&dat.data[1], _countof(buf)-offsetof(SfscAbstruct,SfscAbstruct::data)-1, info.NAME );    dat.b = LFscBase::FLD;    switch( info.PointType )    {    case CFSC_Info::DI:      dat.type = 0x0B;      mList.FuncParser0B( this, obj, dat, temp );      break;    case CFSC_Info::DO:      dat.type = 0x1A;      mList.FuncParser1A( this, obj, dat, temp );      break;    case CFSC_Info::AO:      dat.type = 0x19;      mList.FuncParser19( this, obj, dat, temp );      break;    case CFSC_Info::AI:      dat.type = 0x0C;      mList.FuncParser0C( this, obj, dat, temp );      break;    case CFSC_Info::BI:      dat.type = 0x46;      mList.FuncParser46( this, obj, dat, temp );      break;    default:      ASS(0);      continue;    }    obj.uniNum = mList.Count() - 1;    mList.AddObj( &obj );  }  temp.Clear();  return err_Ok;}